Method.Implementation:
Try {
	Set tStatus = $$$OK
	Set pObject = $$$NULLOREF
	If '$IsObject(pStream) {
		Set tFilename = pStream
		Set pStream = ##class(%IO.FileStream).%New()
		Do pStream.Open(tFilename,,pTimeout,"UTF-8", .tStatus)
		If $$$ISERR(tStatus) Quit
	}
	Set tObjectName = $parameter($this,"OBJECTNAME")
	Set tObject = $classmethod(tObjectName,"%New")
	If '$IsObject(tObject) {
		Set tStatus = $$$ERROR($$$CannotCreateObject,tObjectName)
		Quit
	}
	Set tObject.%Source = pStream.Name
	Set tGetTopFields = $parameter(tObject,"INCLUDETOPFIELDS")
	If pStream.AtEnd && (""=pLookAhead) {
		Set tStatus = $$$ERROR($$$EnsRecordMapErrStreamAtEnd, pStream.Name)
		Quit
	}
	Set pStream.CharEncoding = "UTF-8"

	#; Parse incoming stream
	Set tStatus = ..GetRecord(pStream, tObject, tGetTopFields, pTimeout, .pLookAhead, pLabelFound)
	If $$$ISERR(tStatus) Quit
}
Catch ex {
	Set tStatus = ex.AsStatus()
}
If $$$ISERR(tStatus) { Set pObject = $$$NULLOREF }
Else { Set pObject = tObject }
Quit tStatus

Try {
	Set tStatus = $$$OK
	If '$IsObject(pStream) {
		Set tFilename = pStream
		Set pStream = ##class(%IO.FileStream).%New()
		Do pStream.Open(tFilename,"WAE",,"UTF-8", .tStatus)
		If $$$ISERR(tStatus) Quit
	}
	Set tHasTopFields = $parameter(pObject,"INCLUDETOPFIELDS")
	Set pStream.CharEncoding = "UTF-8"

	Set tStatus = ..PutRecord(pStream, pObject, tHasTopFields, .pPadArray)
	If $$$ISERR(tStatus) Quit
	If pFlush Do pStream.Flush(.tStatus)
	If $$$ISERR(tStatus) Quit
}
Catch ex {
	Set tStatus = ex.AsStatus()
}
Quit tStatus

Set tStatus = $$$OK
Do pStream.Write("OR000",,.tStatus)
If $$$ISERR(tStatus) Quit tStatus
If pHasTopFields { Set tValue = ##class(IHC.ITF.BILLING.DStruc.CBRefundToARM.InCB.Header.Record).RecordCountLogicalToDisplay(pObject.RecordCount), tLen = $length(tValue) }
Else { Set tValue = "", tLen = 0}
If 7 > tLen {
	Set tPadding = $get(pPadArray(7 - tLen))
	If tPadding = "" {
		Set $piece(tPadding, $char(32), (7 - tLen + 1)) = ""
		Set pPadArray(7-tLen) = tPadding
	}
	Set tValue = tValue_tPadding
}
Do pStream.Write(tValue, 0, .tStatus)
If $$$ISERR(tStatus) Quit tStatus
If pHasTopFields { Set tValue = ##class(IHC.ITF.BILLING.DStruc.CBRefundToARM.InCB.Header.Record).DescriptionLogicalToDisplay(pObject.Description), tLen = $length(tValue) }
Else { Set tValue = "", tLen = 0}
If 30 > tLen {
	Set tPadding = $get(pPadArray(30 - tLen))
	If tPadding = "" {
		Set $piece(tPadding, $char(32), (30 - tLen + 1)) = ""
		Set pPadArray(30-tLen) = tPadding
	}
	Set tValue = tValue_tPadding
}
Do pStream.Write(tValue, 0, .tStatus)
If $$$ISERR(tStatus) Quit tStatus
If pHasTopFields { Set tValue = ##class(IHC.ITF.BILLING.DStruc.CBRefundToARM.InCB.Header.Record).DateLogicalToDisplay(pObject.Date), tLen = $length(tValue) }
Else { Set tValue = "", tLen = 0}
If 8 > tLen {
	Set tPadding = $get(pPadArray(8 - tLen))
	If tPadding = "" {
		Set $piece(tPadding, $char(32), (8 - tLen + 1)) = ""
		Set pPadArray(8-tLen) = tPadding
	}
	Set tValue = tValue_tPadding
}
Do pStream.Write(tValue, 0, .tStatus)
If $$$ISERR(tStatus) Quit tStatus
If pHasTopFields { Set tValue = ##class(IHC.ITF.BILLING.DStruc.CBRefundToARM.InCB.Header.Record).TotalDollarsLogicalToDisplay(pObject.TotalDollars), tLen = $length(tValue) }
Else { Set tValue = "", tLen = 0}
If 12 > tLen {
	Set tPadding = $get(pPadArray(12 - tLen))
	If tPadding = "" {
		Set $piece(tPadding, $char(32), (12 - tLen + 1)) = ""
		Set pPadArray(12-tLen) = tPadding
	}
	Set tValue = tValue_tPadding
}
Do pStream.Write(tValue, 0, .tStatus)
If $$$ISERR(tStatus) Quit tStatus
If pHasTopFields { Set tValue = ##class(IHC.ITF.BILLING.DStruc.CBRefundToARM.InCB.Header.Record).BlankFilledLogicalToDisplay(pObject.BlankFilled), tLen = $length(tValue) }
Else { Set tValue = "", tLen = 0}
If 438 > tLen {
	Set tPadding = $get(pPadArray(438 - tLen))
	If tPadding = "" {
		Set $piece(tPadding, $char(32), (438 - tLen + 1)) = ""
		Set pPadArray(438-tLen) = tPadding
	}
	Set tValue = tValue_tPadding
}
Do pStream.Write(tValue, 0, .tStatus)
If $$$ISERR(tStatus) Quit tStatus
Do pStream.Write($char(10), 0, .tStatus)
If $$$ISERR(tStatus) Quit tStatus
Quit tStatus
